code_sketch:
CompletableFuture<Receipt> f = client.authorizeAsync(order)
        .orTimeout(300, TimeUnit.MILLISECONDS);
try {
    return f.join();                  // CompletionException wrapping TimeoutException
} catch (CompletionException e) {
    if (e.getCause() instanceof TimeoutException) throw new ServiceUnavailableException("payment timed out");
    throw e;
}

