Future<Receipt> f = executor.submit(() -> client.authorize(order));
try {
    return f.get(300, TimeUnit.MILLISECONDS);
} catch (TimeoutException e) {
    f.cancel(true);   // interrupt (if honoured) - the task otherwise keeps running
    throw new ServiceUnavailableException("payment timed out");
}
